def survivor_table(group, ids):
    pool = json.load(open(E + '/hardening/pool.json'))
    meta = {m['id']: m for m in pool['groups'][group]}
    src = open(LANE + '/.ufo/evidence/round-46/hardening/%s-counter.py' % group, encoding='utf-8').read().split('\n')
    status = {}
    for line in POOL_BASE[group].splitlines():
        p = line.split()
        if len(p) >= 3 and p[0] == 'MUT':
            status[p[1]] = p[2]
    rows = []
    for i in ids:
        m = meta[i]
        rows.append('| %s | %s | %s | line %d of the round-46 hardened counter: `%s` | %s |' % (
            i, m['kind'], m['desc'], m['line'], src[m['line'] - 1].strip()[:110].replace('|', '/'), status.get(i, '?')))
    return '\n'.join(['| pool id | kind | detail | site | baseline |', '|---|---|---|---|---|'] + rows)


