assert len(W1) == len({n for n, *_ in W1}), 'duplicate names'


def main():
    wave = sys.argv[1] if len(sys.argv) > 1 else 'w1'
    items = {'w1': W1, 'w2': globals().get('W2', [])}[wave]
    spec = build(wave, '.ufo/waves/round-47/%s' % wave, items)
    out = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'spec-%s.json' % wave)
    with open(out, 'w', encoding='utf-8') as fh:
        json.dump(spec, fh, indent=2, ensure_ascii=False)
    roles = {}
    for it in spec['items']:
        roles[it['role']] = roles.get(it['role'], 0) + 1
    print('wrote %s with %d items %s' % (out, len(items), json.dumps(roles, sort_keys=True)))


if __name__ == '__main__':
    main()
